/**
 * Urgency computation for inbox items.
 *
 * Rules:
 *   now       — deposit pending for booking < 24h away; form unsigned for booking < 24h away
 *   today     — pending bookings in next 48h; waitlist signups < 24h old
 *   this_week — new clients < 7d ago (not yet booked); consent forms unsigned > 24h
 *   later     — everything else
 */

import type { InboxItemType } from '@/components/inbox/InboxClient'

export type Urgency = 'now' | 'today' | 'this_week' | 'later'

export interface UrgencyMeta {
  label: string
  /** Tailwind text colour class */
  textClass: string
  /** Tailwind bg colour class for the dot */
  dotClass: string
  /** Tailwind border colour class for the group header */
  borderClass: string
}

export const URGENCY_META: Record<Urgency, UrgencyMeta> = {
  now: {
    label: 'Now',
    textClass: 'text-red-500 dark:text-red-400',
    dotClass: 'bg-red-500',
    borderClass: 'border-red-500/20',
  },
  today: {
    label: 'Today',
    textClass: 'text-amber-500 dark:text-amber-400',
    dotClass: 'bg-amber-500',
    borderClass: 'border-amber-500/20',
  },
  this_week: {
    label: 'This Week',
    textClass: 'text-blue-500 dark:text-blue-400',
    dotClass: 'bg-blue-500',
    borderClass: 'border-blue-500/20',
  },
  later: {
    label: 'Later',
    textClass: 'text-muted-foreground',
    dotClass: 'bg-muted-foreground/40',
    borderClass: 'border-border/30',
  },
}

export const URGENCY_ORDER: Urgency[] = ['now', 'today', 'this_week', 'later']

export interface InboxItemForUrgency {
  type: InboxItemType
  /** ISO timestamp of the item itself (created_at or updated_at) */
  timestamp: string
  /** For deposit / form items: the booking's scheduled_at — ISO string */
  scheduledAt?: string | null
}

/**
 * Compute urgency for a single inbox item.
 * All comparisons are client-side from `Date.now()`.
 */
export function computeUrgency(item: InboxItemForUrgency): Urgency {
  const now = Date.now()
  const h24 = 24 * 60 * 60 * 1000
  const h48 = 48 * 60 * 60 * 1000
  const d7 = 7 * 24 * 60 * 60 * 1000

  const itemAge = now - new Date(item.timestamp).getTime()

  if (item.type === 'deposit') {
    if (item.scheduledAt) {
      const msUntil = new Date(item.scheduledAt).getTime() - now
      if (msUntil >= 0 && msUntil < h24) return 'now'
      if (msUntil >= 0 && msUntil < h48) return 'today'
    }
    return 'later'
  }

  if (item.type === 'form') {
    if (item.scheduledAt) {
      const msUntil = new Date(item.scheduledAt).getTime() - now
      if (msUntil >= 0 && msUntil < h24) return 'now'
    }
    // Form unsigned for >24h → this_week
    if (itemAge > h24) return 'this_week'
    return 'today'
  }

  if (item.type === 'waitlist') {
    // Signups < 24h → today
    if (itemAge < h24) return 'today'
    return 'later'
  }

  if (item.type === 'client') {
    // New clients < 7d → this_week
    if (itemAge < d7) return 'this_week'
    return 'later'
  }

  return 'later'
}

'use server'

import { revalidatePath } from 'next/cache'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio } from '@/lib/context/active-studio'
import { logger } from '@/lib/logger'
import type { InboxItemKind } from '@/lib/supabase/types'

// ─── Types ────────────────────────────────────────────────────

type ActionResult<T = undefined> =
  | { ok: true; data?: T; error?: never }
  | { ok: false; error: string; data?: never }

interface BatchItem {
  kind: InboxItemKind
  id: string
}

// ─── Helpers ──────────────────────────────────────────────────

async function upsertAssignment(
  studioId: string,
  itemKind: InboxItemKind,
  itemId: string,
  patch: Record<string, string | null | boolean>,
): Promise<ActionResult> {
  const supabase = await createClient()

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(
      {
        studio_id: studioId,
        item_kind: itemKind,
        item_id: itemId,
        ...patch,
        updated_at: new Date().toISOString(),
      },
      { onConflict: 'studio_id,item_kind,item_id' },
    )

  if (error) {
    logger.error({ error: error.message, studioId, itemKind, itemId }, 'inbox: upsert failed')
    return { ok: false, error: error.message }
  }

  revalidatePath('/inbox')
  return { ok: true }
}

// ─── Individual actions ───────────────────────────────────────

export async function resolveInboxItemAction(
  itemKind: InboxItemKind,
  itemId: string,
  note?: string,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()

  return upsertAssignment(studioId, itemKind, itemId, {
    resolved_at: new Date().toISOString(),
    ...(note ? { note } : {}),
  })
}

export async function archiveInboxItemAction(
  itemKind: InboxItemKind,
  itemId: string,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()

  return upsertAssignment(studioId, itemKind, itemId, {
    archived_at: new Date().toISOString(),
  })
}

export async function assignInboxItemAction(
  itemKind: InboxItemKind,
  itemId: string,
  assignedTo: string | null,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()

  return upsertAssignment(studioId, itemKind, itemId, {
    assigned_to: assignedTo,
  })
}

export async function snoozeInboxItemAction(
  itemKind: InboxItemKind,
  itemId: string,
  until: Date,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()

  return upsertAssignment(studioId, itemKind, itemId, {
    snoozed_until: until.toISOString(),
  })
}

// ─── Batch actions ────────────────────────────────────────────

export async function batchResolveAction(items: BatchItem[]): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()
  const now = new Date().toISOString()

  const rows = items.map((i) => ({
    studio_id: studioId,
    item_kind: i.kind,
    item_id: i.id,
    resolved_at: now,
    updated_at: now,
  }))

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(rows, { onConflict: 'studio_id,item_kind,item_id' })

  if (error) {
    logger.error({ error: error.message, count: items.length }, 'inbox: batch resolve failed')
    return { ok: false, error: error.message }
  }

  revalidatePath('/inbox')
  return { ok: true }
}

export async function batchArchiveAction(items: BatchItem[]): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()
  const now = new Date().toISOString()

  const rows = items.map((i) => ({
    studio_id: studioId,
    item_kind: i.kind,
    item_id: i.id,
    archived_at: now,
    updated_at: now,
  }))

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(rows, { onConflict: 'studio_id,item_kind,item_id' })

  if (error) {
    logger.error({ error: error.message, count: items.length }, 'inbox: batch archive failed')
    return { ok: false, error: error.message }
  }

  revalidatePath('/inbox')
  return { ok: true }
}

export async function batchAssignAction(
  items: BatchItem[],
  assignedTo: string | null,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()
  const now = new Date().toISOString()

  const rows = items.map((i) => ({
    studio_id: studioId,
    item_kind: i.kind,
    item_id: i.id,
    assigned_to: assignedTo,
    updated_at: now,
  }))

  const { error } = await supabase
    .from('inbox_assignments')
    .upsert(rows, { onConflict: 'studio_id,item_kind,item_id' })

  if (error) {
    logger.error({ error: error.message, count: items.length }, 'inbox: batch assign failed')
    return { ok: false, error: error.message }
  }

  revalidatePath('/inbox')
  return { ok: true }
}

// ─── One-click CTA actions ────────────────────────────────────

/**
 * Send a deposit reminder SMS to the client of the given booking.
 * Fetches booking → client phone → sends via Twilio → records resolved.
 */
export async function sendDepositReminderAction(
  bookingId: string,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()

  // Fetch booking + client
  const { data: booking, error: bookingErr } = await supabase
    .from('bookings')
    .select('id, scheduled_at, clients!inner(first_name, phone)')
    .eq('id', bookingId)
    .eq('studio_id', studioId)
    .single()

  if (bookingErr || !booking) {
    return { ok: false, error: 'Booking not found' }
  }

  const client = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
  const phone = client?.phone

  if (!phone) {
    return { ok: false, error: 'Client has no phone number on file' }
  }

  // Send SMS
  try {
    const { sendSms, TwilioNotConfiguredError } = await import('@/lib/sms/twilio')
    const firstName = client.first_name ?? 'there'
    const scheduledDate = new Date(booking.scheduled_at).toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
    })
    await sendSms({
      to: phone,
      body: `Hi ${firstName} — a reminder that your deposit is still outstanding for your appointment on ${scheduledDate}. Please pay to secure your slot. Reply STOP to opt out.`,
    })
  } catch (err) {
    if (err instanceof Error && err.constructor.name === 'TwilioNotConfiguredError') {
      logger.warn({ bookingId }, 'inbox: Twilio not configured — SMS skipped')
    } else {
      logger.error({ err, bookingId }, 'inbox: SMS send failed')
      return { ok: false, error: 'Failed to send SMS' }
    }
  }

  // Mark resolved
  const resolveResult = await upsertAssignment(studioId, 'deposit', bookingId, {
    resolved_at: new Date().toISOString(),
    note: 'Deposit reminder SMS sent',
  })

  return resolveResult
}

/**
 * Resend the consent form link for a given submission.
 */
export async function resendFormLinkAction(
  submissionId: string,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()

  const { data: submission, error: subErr } = await supabase
    .from('consent_form_submissions')
    .select('id, token, clients!inner(first_name, email)')
    .eq('id', submissionId)
    .eq('studio_id', studioId)
    .single()

  if (subErr || !submission) {
    return { ok: false, error: 'Submission not found' }
  }

  const client = Array.isArray(submission.clients) ? submission.clients[0] : submission.clients
  const email = client?.email

  if (!email) {
    return { ok: false, error: 'Client has no email on file' }
  }

  try {
    const { sendEmail } = await import('@/lib/email/resend')
    const formUrl = `${process.env.NEXT_PUBLIC_APP_URL ?? ''}/consent/${submission.token}`
    await sendEmail({
      to: email,
      template: 'booking_confirmation',
      data: {
        studioName: 'Your Studio',
        clientFirstName: client.first_name ?? 'there',
        serviceName: 'Your appointment',
        artistName: '',
        scheduledAt: new Date().toISOString(),
        endAt: new Date().toISOString(),
        durationMin: 0,
        priceCents: 0,
        depositCents: 0,
        depositPaid: false,
        bookingReference: '',
        depositPaymentUrl: formUrl,
      },
    })
  } catch (err) {
    logger.error({ err, submissionId }, 'inbox: form link resend failed')
    return { ok: false, error: 'Failed to send email' }
  }

  const resolveResult = await upsertAssignment(studioId, 'form', submissionId, {
    resolved_at: new Date().toISOString(),
    note: 'Form link resent via email',
  })

  return resolveResult
}

/**
 * Send a welcome email to a new client.
 */
export async function sendWelcomeAction(
  clientId: string,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()

  const { data: client, error: clientErr } = await supabase
    .from('clients')
    .select('id, first_name, email')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (clientErr || !client) {
    return { ok: false, error: 'Client not found' }
  }

  if (!client.email) {
    return { ok: false, error: 'Client has no email on file' }
  }

  try {
    const { sendEmail } = await import('@/lib/email/resend')
    await sendEmail({
      to: client.email,
      template: 'booking_confirmation',
      data: {
        studioName: 'Your Studio',
        clientFirstName: client.first_name ?? 'there',
        serviceName: '',
        artistName: '',
        scheduledAt: new Date().toISOString(),
        endAt: new Date().toISOString(),
        durationMin: 0,
        priceCents: 0,
        depositCents: 0,
        depositPaid: false,
        bookingReference: '',
      },
    })
  } catch (err) {
    logger.error({ err, clientId }, 'inbox: welcome email failed')
    return { ok: false, error: 'Failed to send welcome email' }
  }

  const resolveResult = await upsertAssignment(studioId, 'client', clientId, {
    resolved_at: new Date().toISOString(),
    note: 'Welcome email sent',
  })

  return resolveResult
}

/**
 * Returns pre-fill data for the booking drawer when offering a slot
 * to a waitlist entry. This action does not create a booking.
 */
export async function offerWaitlistSlotAction(
  waitlistEntryId: string,
): Promise<ActionResult<{ clientId: string; notes: string | null; serviceId: string | null; artistId: string | null }>> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()

  const { data: entry, error } = await supabase
    .from('waitlist_entries')
    .select('id, client_id, notes, service_id, artist_id')
    .eq('id', waitlistEntryId)
    .eq('studio_id', studioId)
    .single()

  if (error || !entry) {
    return { ok: false, error: 'Waitlist entry not found' }
  }

  return {
    ok: true,
    data: {
      clientId: entry.client_id,
      notes: entry.notes,
      serviceId: entry.service_id,
      artistId: entry.artist_id,
    },
  }
}

'use client'

import { useState, useTransition } from 'react'
import { Check, ChevronsUpDown, UserMinus } from 'lucide-react'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from '@/components/ui/command'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { Button } from '@/components/ui/button'
import { Avatar, AvatarFallback } from '@/components/ui/avatar'
import { cn } from '@/lib/utils'

export interface TeamMember {
  userId: string
  name: string
  role: string
  avatarUrl: string | null
}

interface AssignUserPickerProps {
  members: TeamMember[]
  currentUserId: string
  currentAssignee: string | null
  onAssign: (userId: string | null) => Promise<void>
  /** Render as icon-only on mobile */
  compact?: boolean
}

function initials(name: string): string {
  return name
    .split(' ')
    .map((p) => p[0] ?? '')
    .join('')
    .toUpperCase()
    .slice(0, 2)
}

export function AssignUserPicker({
  members,
  currentUserId,
  currentAssignee,
  onAssign,
  compact = false,
}: AssignUserPickerProps) {
  const [open, setOpen] = useState(false)
  const [isPending, startTransition] = useTransition()

  const currentMember = members.find((m) => m.userId === currentAssignee) ?? null
  const buttonLabel = currentMember
    ? currentMember.userId === currentUserId
      ? 'You'
      : currentMember.name
    : 'Assign'

  function handleSelect(userId: string | null) {
    startTransition(async () => {
      await onAssign(userId)
    })
    setOpen(false)
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="ghost"
          size="sm"
          role="combobox"
          aria-expanded={open}
          aria-label="Assign to team member"
          disabled={isPending}
          className={cn(
            'h-7 gap-1.5 text-xs text-muted-foreground hover:text-foreground',
            compact && 'w-7 px-0',
          )}
        >
          {currentMember ? (
            <Avatar className="h-4 w-4">
              <AvatarFallback className="text-[8px]">
                {initials(currentMember.name)}
              </AvatarFallback>
            </Avatar>
          ) : null}
          {!compact && <span>{buttonLabel}</span>}
          {!compact && <ChevronsUpDown className="h-3 w-3 shrink-0 opacity-50" aria-hidden="true" />}
        </Button>
      </PopoverTrigger>

      <PopoverContent className="w-52 p-0" align="end">
        <Command>
          <CommandInput placeholder="Search team..." className="h-8 text-xs" />
          <CommandList>
            <CommandEmpty className="py-4 text-center text-xs text-muted-foreground">
              No team members found
            </CommandEmpty>
            <CommandGroup heading="Team members">
              {members.map((member) => {
                const isSelected = currentAssignee === member.userId
                const isYou = member.userId === currentUserId
                return (
                  <CommandItem
                    key={member.userId}
                    value={member.name}
                    onSelect={() => handleSelect(member.userId)}
                    className="gap-2 text-xs"
                  >
                    <Avatar className="h-5 w-5 shrink-0">
                      <AvatarFallback className="text-[9px]">
                        {initials(member.name)}
                      </AvatarFallback>
                    </Avatar>
                    <span className="flex-1 truncate">
                      {member.name}
                      {isYou && (
                        <span className="ml-1 text-muted-foreground">(You)</span>
                      )}
                    </span>
                    <span className="text-[10px] capitalize text-muted-foreground/60">
                      {member.role}
                    </span>
                    {isSelected && (
                      <Check className="h-3 w-3 shrink-0 text-primary" aria-hidden="true" />
                    )}
                  </CommandItem>
                )
              })}
            </CommandGroup>
            <CommandSeparator />
            <CommandGroup>
              <CommandItem
                value="unassigned"
                onSelect={() => handleSelect(null)}
                className="gap-2 text-xs text-muted-foreground"
              >
                <UserMinus className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
                Unassigned
                {currentAssignee === null && (
                  <Check className="ml-auto h-3 w-3 shrink-0 text-primary" aria-hidden="true" />
                )}
              </CommandItem>
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

'use client'

import { useState } from 'react'
import { ChevronDown, ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Urgency } from '@/lib/inbox/urgency'
import { URGENCY_META } from '@/lib/inbox/urgency'

interface UrgencyGroupProps {
  urgency: Urgency
  count: number
  defaultExpanded?: boolean
  children: React.ReactNode
}

export function UrgencyGroup({
  urgency,
  count,
  defaultExpanded = true,
  children,
}: UrgencyGroupProps) {
  const [expanded, setExpanded] = useState(defaultExpanded)
  const meta = URGENCY_META[urgency]

  return (
    <section
      aria-label={`${meta.label} (${count} items)`}
      className={cn('rounded-lg border', meta.borderClass)}
    >
      {/* Group header */}
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        aria-expanded={expanded}
        className={cn(
          'flex w-full items-center gap-2 rounded-t-lg px-4 py-2.5 transition-colors hover:bg-muted/20',
          !expanded && 'rounded-b-lg',
        )}
      >
        {/* Urgency dot */}
        <span
          className={cn('h-2 w-2 shrink-0 rounded-full', meta.dotClass)}
          aria-hidden="true"
        />

        {/* Label */}
        <span className={cn('text-[12px] font-semibold tracking-wide uppercase', meta.textClass)}>
          {meta.label}
        </span>

        {/* Count badge */}
        <span className="rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">
          {count}
        </span>

        {/* Expand/collapse chevron */}
        <span className="ml-auto text-muted-foreground/60" aria-hidden="true">
          {expanded
            ? <ChevronDown className="h-3.5 w-3.5" />
            : <ChevronRight className="h-3.5 w-3.5" />
          }
        </span>
      </button>

      {/* Items */}
      {expanded && (
        <div
          className="divide-y divide-border/30 rounded-b-lg"
          role="list"
          aria-label={`${meta.label} items`}
        >
          {children}
        </div>
      )}
    </section>
  )
}

