'use client'

import { useTransition } from 'react'
import Link from 'next/link'
import {
  Archive,
  CheckCircle2,
  Clock,
  FileText,
  Mail,
  MoreHorizontal,
  MessageSquare,
  UserCheck,
  UserPlus,
  Zap,
} from 'lucide-react'
import { format, formatDistanceToNow } from 'date-fns'
import { toast } from 'sonner'
import { Checkbox } from '@/components/ui/checkbox'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Avatar, AvatarFallback } from '@/components/ui/avatar'
import { cn } from '@/lib/utils'
import type { Urgency } from '@/lib/inbox/urgency'
import { URGENCY_META } from '@/lib/inbox/urgency'
import type { TeamMember } from './AssignUserPicker'
import { AssignUserPicker } from './AssignUserPicker'
import type { RichInboxItem } from './InboxClient'
import {
  archiveInboxItemAction,
  resolveInboxItemAction,
  assignInboxItemAction,
  sendDepositReminderAction,
  resendFormLinkAction,
  sendWelcomeAction,
} from '@/app/(app)/inbox/actions'
import type { InboxItemKind } from '@/lib/supabase/types'

interface InboxItemRowProps {
  item: RichInboxItem
  urgency: Urgency
  isSelected: boolean
  isFocused: boolean
  members: TeamMember[]
  currentUserId: string
  onToggleSelect: (id: string) => void
  onFocus: (id: string) => void
  onRefresh: () => void
}

function typeIcon(type: InboxItemKind) {
  switch (type) {
    case 'deposit': return <CheckCircle2 className="h-4 w-4 text-amber-500" aria-hidden="true" />
    case 'form': return <FileText className="h-4 w-4 text-blue-500" aria-hidden="true" />
    case 'client': return <UserPlus className="h-4 w-4 text-emerald-500" aria-hidden="true" />
    case 'waitlist': return <Clock className="h-4 w-4 text-purple-500" aria-hidden="true" />
  }
}

function typeBg(type: InboxItemKind): string {
  switch (type) {
    case 'deposit': return 'bg-amber-500/10'
    case 'form': return 'bg-blue-500/10'
    case 'client': return 'bg-emerald-500/10'
    case 'waitlist': return 'bg-purple-500/10'
  }
}

function ctaLabel(type: InboxItemKind): string {
  switch (type) {
    case 'deposit': return 'Send reminder'
    case 'form': return 'Resend link'
    case 'client': return 'Send welcome'
    case 'waitlist': return 'Offer slot'
  }
}

function ctaIcon(type: InboxItemKind) {
  switch (type) {
    case 'deposit': return <MessageSquare className="h-3 w-3" aria-hidden="true" />
    case 'form': return <Mail className="h-3 w-3" aria-hidden="true" />
    case 'client': return <Mail className="h-3 w-3" aria-hidden="true" />
    case 'waitlist': return <Zap className="h-3 w-3" aria-hidden="true" />
  }
}

function initials(name: string): string {
  return name
    .split(' ')
    .map((p) => p[0] ?? '')
    .join('')
    .toUpperCase()
    .slice(0, 2)
}

export function InboxItemRow({
  item,
  urgency,
  isSelected,
  isFocused,
  members,
  currentUserId,
  onToggleSelect,
  onFocus,
  onRefresh,
}: InboxItemRowProps) {
  const [isPending, startTransition] = useTransition()
  const meta = URGENCY_META[urgency]
  const ts = new Date(item.timestamp)
  const isRecent = Date.now() - ts.getTime() < 24 * 60 * 60 * 1000

  // Extract the raw UUID from composite id like "booking-<uuid>"
  const rawId = item.id.replace(/^(booking|consent|waitlist|client)-/, '')

  const assignedMember = members.find((m) => m.userId === item.assignedTo) ?? null

  function handleCta() {
    startTransition(async () => {
      let result: { ok: boolean; error?: string }

      if (item.type === 'deposit') {
        result = await sendDepositReminderAction(rawId)
        if (result.ok) {
          toast.success('Deposit reminder sent')
          onRefresh()
        } else {
          toast.error(result.error ?? 'Failed to send reminder')
        }
        return
      }

      if (item.type === 'form') {
        result = await resendFormLinkAction(rawId)
        if (result.ok) {
          toast.success('Form link resent')
          onRefresh()
        } else {
          toast.error(result.error ?? 'Failed to resend link')
        }
        return
      }

      if (item.type === 'client') {
        result = await sendWelcomeAction(rawId)
        if (result.ok) {
          toast.success('Welcome email sent')
          onRefresh()
        } else {
          toast.error(result.error ?? 'Failed to send welcome email')
        }
        return
      }

      if (item.type === 'waitlist') {
        // Waitlist CTA opens the booking drawer — we just navigate to bookings/new
        // with a query param. The drawer is pre-filled by the server action on that page.
        window.location.href = `/bookings/new?waitlist=${rawId}`
      }
    })
  }

  function handleResolve() {
    startTransition(async () => {
      const result = await resolveInboxItemAction(item.type, rawId)
      if (result.ok) {
        toast.success('Marked as resolved')
        onRefresh()
      } else {
        toast.error(result.error ?? 'Failed to resolve')
      }
    })
  }

  function handleArchive() {
    startTransition(async () => {
      const result = await archiveInboxItemAction(item.type, rawId)
      if (result.ok) {
        toast.success('Archived')
        onRefresh()
      } else {
        toast.error(result.error ?? 'Failed to archive')
      }
    })
  }

  async function handleAssign(userId: string | null) {
    const result = await assignInboxItemAction(item.type, rawId, userId)
    if (result.ok) {
      toast.success(userId ? 'Assigned' : 'Unassigned')
      onRefresh()
    } else {
      toast.error(result.error ?? 'Failed to assign')
    }
  }

  return (
    <div
      role="listitem"
      data-inbox-item-id={item.id}
      aria-selected={isSelected}
      onClick={() => onFocus(item.id)}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault()
          onFocus(item.id)
        }
      }}
      tabIndex={0}
      className={cn(
        'group flex items-center gap-3 bg-card px-4 py-3 transition-colors',
        'hover:bg-muted/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30',
        isFocused && 'bg-primary/5 ring-1 ring-inset ring-primary/20',
        isSelected && 'bg-primary/5',
        isPending && 'opacity-60',
        'last:rounded-b-lg',
      )}
    >
      {/* Checkbox */}
      <Checkbox
        checked={isSelected}
        onCheckedChange={() => onToggleSelect(item.id)}
        onClick={(e) => e.stopPropagation()}
        aria-label={`Select ${item.title}`}
        className="shrink-0"
      />

      {/* Urgency dot */}
      <span
        className={cn('h-1.5 w-1.5 shrink-0 rounded-full', meta.dotClass)}
        aria-hidden="true"
      />

      {/* Type icon */}
      <div className={cn('flex h-8 w-8 shrink-0 items-center justify-center rounded-full', typeBg(item.type))}>
        {typeIcon(item.type)}
      </div>

      {/* Content */}
      <div className="min-w-0 flex-1">
        <p className="truncate text-[13px] font-medium text-foreground leading-tight">
          {item.title}
        </p>
        <p className="truncate text-[12px] text-muted-foreground">{item.subtitle}</p>
      </div>

      {/* Assignee avatar */}
      {assignedMember && (
        <Avatar className="h-6 w-6 shrink-0" aria-label={`Assigned to ${assignedMember.name}`}>
          <AvatarFallback className="text-[9px] bg-muted">
            {initials(assignedMember.name)}
          </AvatarFallback>
        </Avatar>
      )}

      {/* Timestamp */}
      <time
        dateTime={item.timestamp}
        className="shrink-0 text-[11px] text-muted-foreground/60 hidden sm:block"
        title={format(ts, 'PPpp')}
      >
        {isRecent ? formatDistanceToNow(ts, { addSuffix: true }) : format(ts, 'MMM d')}
      </time>

      {/* One-click CTA */}
      <Button
        variant="outline"
        size="sm"
        onClick={(e) => { e.stopPropagation(); handleCta() }}
        disabled={isPending}
        className="shrink-0 h-7 gap-1.5 text-[11px] hidden sm:flex"
        aria-label={`${ctaLabel(item.type)} for ${item.title}`}
      >
        {ctaIcon(item.type)}
        <span className="hidden md:inline">{ctaLabel(item.type)}</span>
      </Button>

      {/* Mobile: icon-only CTA */}
      <Button
        variant="outline"
        size="sm"
        onClick={(e) => { e.stopPropagation(); handleCta() }}
        disabled={isPending}
        className="shrink-0 h-7 w-7 p-0 sm:hidden"
        aria-label={ctaLabel(item.type)}
      >
        {ctaIcon(item.type)}
      </Button>

      {/* Kebab menu */}
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            variant="ghost"
            size="sm"
            onClick={(e) => e.stopPropagation()}
            className="h-7 w-7 shrink-0 p-0 text-muted-foreground/60 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 focus-visible:opacity-100"
            aria-label="More options"
          >
            <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" side="bottom">
          <DropdownMenuItem
            onClick={(e) => { e.stopPropagation(); handleResolve() }}
            className="gap-2 text-xs"
          >
            <UserCheck className="h-3.5 w-3.5" aria-hidden="true" />
            Mark resolved
          </DropdownMenuItem>
          <DropdownMenuItem
            onClick={(e) => { e.stopPropagation(); handleArchive() }}
            className="gap-2 text-xs"
          >
            <Archive className="h-3.5 w-3.5" aria-hidden="true" />
            Archive
          </DropdownMenuItem>
          <DropdownMenuSeparator />
          {/* View link */}
          <DropdownMenuItem asChild className="gap-2 text-xs">
            <Link href={item.actionHref} onClick={(e) => e.stopPropagation()}>
              View details
            </Link>
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>

      {/* Assign picker — hidden on mobile */}
      <div className="hidden sm:block" onClick={(e) => e.stopPropagation()}>
        <AssignUserPicker
          members={members}
          currentUserId={currentUserId}
          currentAssignee={item.assignedTo}
          onAssign={handleAssign}
          compact
        />
      </div>
    </div>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { Archive, CheckCheck, UserCheck, X, BellOff } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { AssignUserPicker } from './AssignUserPicker'
import type { TeamMember } from './AssignUserPicker'
import type { InboxItemKind } from '@/lib/supabase/types'
import {
  batchResolveAction,
  batchArchiveAction,
  batchAssignAction,
} from '@/app/(app)/inbox/actions'

interface SelectedItem {
  id: string
  type: InboxItemKind
}

interface BatchActionBarProps {
  selected: SelectedItem[]
  members: TeamMember[]
  currentUserId: string
  onClear: () => void
  onRefresh: () => void
}

function toBatchItems(selected: SelectedItem[]) {
  return selected.map((s) => ({
    kind: s.type,
    id: s.id.replace(/^(booking|consent|waitlist|client)-/, ''),
  }))
}

export function BatchActionBar({
  selected,
  members,
  currentUserId,
  onClear,
  onRefresh,
}: BatchActionBarProps) {
  const [isPending, startTransition] = useTransition()
  const count = selected.length

  if (count === 0) return null

  function handleResolveAll() {
    startTransition(async () => {
      const result = await batchResolveAction(toBatchItems(selected))
      if (result.ok) {
        toast.success(`Resolved ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch resolve failed')
      }
    })
  }

  function handleArchiveAll() {
    startTransition(async () => {
      const result = await batchArchiveAction(toBatchItems(selected))
      if (result.ok) {
        toast.success(`Archived ${count} item${count > 1 ? 's' : ''}`)
        onClear()
        onRefresh()
      } else {
        toast.error(result.error ?? 'Batch archive failed')
      }
    })
  }

  async function handleAssignAll(userId: string | null) {
    const result = await batchAssignAction(toBatchItems(selected), userId)
    if (result.ok) {
      toast.success(
        userId
          ? `Assigned ${count} item${count > 1 ? 's' : ''}`
          : `Unassigned ${count} item${count > 1 ? 's' : ''}`,
      )
      onClear()
      onRefresh()
    } else {
      toast.error(result.error ?? 'Batch assign failed')
    }
  }

  return (
    <div
      role="toolbar"
      aria-label="Batch actions"
      aria-live="polite"
      className="flex items-center gap-2 rounded-lg border border-primary/20 bg-primary/5 px-4 py-2 text-sm"
    >
      {/* Count + clear */}
      <span className="font-medium text-foreground text-[13px]">
        {count} selected
      </span>
      <button
        type="button"
        onClick={onClear}
        className="flex items-center gap-1 text-muted-foreground hover:text-foreground transition-colors text-xs"
        aria-label="Clear selection"
      >
        <X className="h-3 w-3" aria-hidden="true" />
        Clear
      </button>

      <div className="ml-auto flex items-center gap-2">
        {/* Resolve all */}
        <Button
          size="sm"
          variant="outline"
          onClick={handleResolveAll}
          disabled={isPending}
          className="h-7 gap-1.5 text-xs"
        >
          <CheckCheck className="h-3.5 w-3.5" aria-hidden="true" />
          <span className="hidden sm:inline">Resolve all</span>
        </Button>

        {/* Archive all */}
        <Button
          size="sm"
          variant="outline"
          onClick={handleArchiveAll}
          disabled={isPending}
          className="h-7 gap-1.5 text-xs"
        >
          <Archive className="h-3.5 w-3.5" aria-hidden="true" />
          <span className="hidden sm:inline">Archive all</span>
        </Button>

        {/* Assign to... */}
        <AssignUserPicker
          members={members}
          currentUserId={currentUserId}
          currentAssignee={null}
          onAssign={handleAssignAll}
        />
      </div>
    </div>
  )
}

'use client'

import { useState, useCallback, useRef, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { Inbox, Keyboard } from 'lucide-react'
import { EmptyState } from '@/components/shared/EmptyState'
import { PageHeader } from '@/components/shared/PageHeader'
import { PageTabs } from '@/components/shared/PageTabs'
import { useSearchParams } from 'next/navigation'
import { cn } from '@/lib/utils'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { PageTab } from '@/components/shared/PageTabs'
import type { InboxItemKind } from '@/lib/supabase/types'
import { computeUrgency, URGENCY_ORDER, URGENCY_META } from '@/lib/inbox/urgency'
import type { Urgency } from '@/lib/inbox/urgency'
import { UrgencyGroup } from './UrgencyGroup'
import { InboxItemRow } from './InboxItemRow'
import { BatchActionBar } from './BatchActionBar'
import type { TeamMember } from './AssignUserPicker'
import { useInboxShortcuts, INBOX_SHORTCUTS } from '@/hooks/use-inbox-shortcuts'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'

// ─── Types ────────────────────────────────────────────────────

export type InboxItemType = InboxItemKind

export interface InboxItem {
  id: string
  type: InboxItemType
  title: string
  subtitle: string
  actionLabel: string
  actionHref: string
  timestamp: string
}

/** Extended item with urgency-related fields and assignment state */
export interface RichInboxItem extends InboxItem {
  scheduledAt: string | null
  assignedTo: string | null
  resolvedAt: string | null
  archivedAt: string | null
  snoozedUntil: string | null
}

interface InboxClientProps {
  items: RichInboxItem[]
  members: TeamMember[]
  currentUserId: string
  currentPlan: PlanTier
  currentRole: NavRole
}

type TabKey = 'all' | 'deposits' | 'forms' | 'clients'

const VALID_TABS: TabKey[] = ['all', 'deposits', 'forms', 'clients']

const TABS: PageTab[] = [
  { key: 'all', label: 'All', href: '/inbox' },
  { key: 'deposits', label: 'Deposits', href: '/inbox?tab=deposits' },
  { key: 'forms', label: 'Forms', href: '/inbox?tab=forms' },
  { key: 'clients', label: 'Clients', href: '/inbox?tab=clients' },
]

// ─── Component ────────────────────────────────────────────────

export function InboxClient({
  items,
  members,
  currentUserId,
  currentPlan,
  currentRole,
}: InboxClientProps) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const rawTab = searchParams.get('tab')
  const activeTab: TabKey = VALID_TABS.includes(rawTab as TabKey) ? (rawTab as TabKey) : 'all'

  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [focusedId, setFocusedId] = useState<string | null>(null)
  const [showCheatsheet, setShowCheatsheet] = useState(false)
  const [showArchived, setShowArchived] = useState(false)

  // Filter by tab
  const tabFiltered = activeTab === 'all'
    ? items
    : items.filter((item) => {
        if (activeTab === 'deposits') return item.type === 'deposit'
        if (activeTab === 'forms') return item.type === 'form'
        if (activeTab === 'clients') return item.type === 'client' || item.type === 'waitlist'
        return true
      })

  // Filter out archived/resolved unless showArchived is true
  const visibleItems = tabFiltered.filter((item) => {
    if (showArchived) return true
    const isHidden =
      (item.archivedAt !== null) ||
      (item.resolvedAt !== null)
    return !isHidden
  })

  // Group by urgency
  const groups: Record<Urgency, RichInboxItem[]> = {
    now: [],
    today: [],
    this_week: [],
    later: [],
  }

  for (const item of visibleItems) {
    const urgency = computeUrgency({
      type: item.type,
      timestamp: item.timestamp,
      scheduledAt: item.scheduledAt,
    })
    groups[urgency].push(item)
  }

  // Build flat ordered list for keyboard nav
  const orderedItems = URGENCY_ORDER.flatMap((u) => groups[u])

  // ── Selection helpers ──
  const toggleSelect = useCallback((id: string) => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  const clearSelection = useCallback(() => setSelected(new Set()), [])

  // ── Focus helpers ──
  const focusItem = useCallback((id: string) => {
    setFocusedId(id)
    // Scroll item into view
    const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${id}"]`)
    el?.focus()
    el?.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
  }, [])

  // ── Refresh: push the current URL to re-run Server Component ──
  const refresh = useCallback(() => {
    router.refresh()
  }, [router])

  // ── Keyboard shortcuts ──
  useInboxShortcuts({
    onNavigateDown: () => {
      if (orderedItems.length === 0) return
      const currentIdx = orderedItems.findIndex((i) => i.id === focusedId)
      const nextIdx = currentIdx === -1 ? 0 : Math.min(currentIdx + 1, orderedItems.length - 1)
      focusItem(orderedItems[nextIdx].id)
    },
    onNavigateUp: () => {
      if (orderedItems.length === 0) return
      const currentIdx = orderedItems.findIndex((i) => i.id === focusedId)
      const prevIdx = currentIdx <= 0 ? 0 : currentIdx - 1
      focusItem(orderedItems[prevIdx].id)
    },
    onArchiveFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      // Trigger archive via the row's kebab — for keyboard, find the button
      const archiveBtn = el?.querySelector<HTMLElement>('[aria-label="More options"]')
      archiveBtn?.click()
    },
    onAssignFocused: () => {
      if (!focusedId) return
      // Open the assign picker on the focused row
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      const assignBtn = el?.querySelector<HTMLElement>('[aria-label="Assign to team member"]')
      assignBtn?.click()
    },
    onResolveFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      // Click the kebab to trigger resolve
      const moreBtn = el?.querySelector<HTMLElement>('[aria-label="More options"]')
      moreBtn?.click()
    },
    onToggleFocusedCheckbox: () => {
      if (!focusedId) return
      toggleSelect(focusedId)
    },
    onShowCheatsheet: () => setShowCheatsheet(true),
  })

  // ── Tabs with badge ──
  const tabs: PageTab[] = TABS.map((t) =>
    t.key === 'all' && visibleItems.length > 0
      ? { ...t, badge: visibleItems.length }
      : t,
  )

  const selectedItems = orderedItems
    .filter((i) => selected.has(i.id))
    .map((i) => ({ id: i.id, type: i.type }))

  const hasAnyItems = visibleItems.length > 0
  const hasNonEmpty = URGENCY_ORDER.some((u) => groups[u].length > 0)

  return (
    <>
      <div className="flex min-h-full flex-col bg-[var(--color-page-bg)]">
        <PageHeader
          title="Inbox"
          description="Action items that need your attention"
          actions={
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowCheatsheet(true)}
              aria-label="Show keyboard shortcuts"
              className="h-8 w-8 p-0 text-muted-foreground/60 hover:text-foreground"
            >
              <Keyboard className="h-4 w-4" aria-hidden="true" />
            </Button>
          }
        />

        <div className="px-6">
          <PageTabs
            tabs={tabs}
            activeKey={activeTab}
            currentPlan={currentPlan}
            currentRole={currentRole}
            className="mb-4"
          />
        </div>

        {/* Batch action bar */}
        {selected.size > 0 && (
          <div className="px-6 mb-3" aria-live="polite">
            <BatchActionBar
              selected={selectedItems}
              members={members}
              currentUserId={currentUserId}
              onClear={clearSelection}
              onRefresh={refresh}
            />
          </div>
        )}

        {/* Archived toggle */}
        <div className="px-6 mb-2 flex items-center justify-end">
          <button
            type="button"
            onClick={() => setShowArchived((v) => !v)}
            className="text-[11px] text-muted-foreground/60 hover:text-muted-foreground transition-colors"
          >
            {showArchived ? 'Hide archived' : 'Show archived & resolved'}
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 space-y-3 px-6 pb-8">
          {!hasNonEmpty ? (
            <EmptyState
              icon={Inbox}
              title="Inbox is clear"
              description={
                activeTab === 'all'
                  ? "You're all caught up. New action items appear here automatically."
                  : 'No items in this category right now.'
              }
            />
          ) : (
            URGENCY_ORDER.map((urgency) => {
              const groupItems = groups[urgency]
              if (groupItems.length === 0) return null
              const defaultExpanded = urgency === 'now' || urgency === 'today'

              return (
                <UrgencyGroup
                  key={urgency}
                  urgency={urgency}
                  count={groupItems.length}
                  defaultExpanded={defaultExpanded}
                >
                  {groupItems.map((item) => (
                    <InboxItemRow
                      key={item.id}
                      item={item}
                      urgency={urgency}
                      isSelected={selected.has(item.id)}
                      isFocused={focusedId === item.id}
                      members={members}
                      currentUserId={currentUserId}
                      onToggleSelect={toggleSelect}
                      onFocus={setFocusedId}
                      onRefresh={refresh}
                    />
                  ))}
                </UrgencyGroup>
              )
            })
          )}
        </div>
      </div>

      {/* Keyboard cheatsheet modal */}
      <Dialog open={showCheatsheet} onOpenChange={setShowCheatsheet}>
        <DialogContent className="max-w-xs">
          <DialogHeader>
            <DialogTitle className="text-sm font-semibold">Keyboard shortcuts</DialogTitle>
          </DialogHeader>
          <div className="mt-2 space-y-1.5">
            {INBOX_SHORTCUTS.map(({ key, description }) => (
              <div key={key} className="flex items-center justify-between gap-4">
                <span className="text-xs text-muted-foreground">{description}</span>
                <kbd className="inline-flex h-5 min-w-5 items-center justify-center rounded border border-border/60 bg-muted px-1 text-[10px] font-mono text-foreground">
                  {key}
                </kbd>
              </div>
            ))}
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}

