'use client'

import { useState, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { useSearchParams } from 'next/navigation'
import { Inbox, Keyboard } from 'lucide-react'
import { EmptyState } from '@/components/shared/EmptyState'
import { PageHeader } from '@/components/shared/PageHeader'
import { PageTabs } from '@/components/shared/PageTabs'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { cn } from '@/lib/utils'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { PageTab } from '@/components/shared/PageTabs'
import type { InboxItemKind } from '@/lib/supabase/types'
import { computeUrgency, URGENCY_ORDER } from '@/lib/inbox/urgency'
import type { Urgency } from '@/lib/inbox/urgency'
import { UrgencyGroup } from './UrgencyGroup'
import { InboxItemRow } from './InboxItemRow'
import { BatchActionBar } from './BatchActionBar'
import type { TeamMember } from './AssignUserPicker'
import { useInboxShortcuts, INBOX_SHORTCUTS } from '@/hooks/use-inbox-shortcuts'

// ─── Types ────────────────────────────────────────────────────

export type InboxItemType = InboxItemKind

export interface InboxItem {
  id: string
  type: InboxItemType
  title: string
  subtitle: string
  actionLabel: string
  actionHref: string
  timestamp: string
}

/** Extended item with urgency-related fields and assignment state */
export interface RichInboxItem extends InboxItem {
  scheduledAt: string | null
  assignedTo: string | null
  resolvedAt: string | null
  archivedAt: string | null
  snoozedUntil: string | null
}

interface InboxClientProps {
  items: RichInboxItem[]
  members: TeamMember[]
  currentUserId: string
  currentPlan: PlanTier
  currentRole: NavRole
}

type TabKey = 'all' | 'deposits' | 'forms' | 'clients'

const VALID_TABS: TabKey[] = ['all', 'deposits', 'forms', 'clients']

const TABS: PageTab[] = [
  { key: 'all', label: 'All', href: '/inbox' },
  { key: 'deposits', label: 'Deposits', href: '/inbox?tab=deposits' },
  { key: 'forms', label: 'Forms', href: '/inbox?tab=forms' },
  { key: 'clients', label: 'Clients', href: '/inbox?tab=clients' },
]

interface SelectedItem {
  id: string
  type: InboxItemKind
}

// ─── Component ────────────────────────────────────────────────

export function InboxClient({
  items,
  members,
  currentUserId,
  currentPlan,
  currentRole,
}: InboxClientProps) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const rawTab = searchParams.get('tab')
  const activeTab: TabKey = VALID_TABS.includes(rawTab as TabKey) ? (rawTab as TabKey) : 'all'

  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [focusedId, setFocusedId] = useState<string | null>(null)
  const [showCheatsheet, setShowCheatsheet] = useState(false)
  const [showArchived, setShowArchived] = useState(false)

  // Filter by tab
  const tabFiltered: RichInboxItem[] = activeTab === 'all'
    ? items
    : items.filter((item) => {
        if (activeTab === 'deposits') return item.type === 'deposit'
        if (activeTab === 'forms') return item.type === 'form'
        if (activeTab === 'clients') return item.type === 'client' || item.type === 'waitlist'
        return true
      })

  // Filter out archived/resolved unless showArchived
  const visibleItems: RichInboxItem[] = tabFiltered.filter((item) => {
    if (showArchived) return true
    return item.archivedAt === null && item.resolvedAt === null
  })

  // Group by urgency
  const groups: Record<Urgency, RichInboxItem[]> = {
    now: [],
    today: [],
    this_week: [],
    later: [],
  }

  for (const item of visibleItems) {
    const urgency = computeUrgency({
      type: item.type,
      timestamp: item.timestamp,
      scheduledAt: item.scheduledAt,
    })
    groups[urgency].push(item)
  }

  // Flat ordered list for keyboard nav
  const orderedItems: RichInboxItem[] = URGENCY_ORDER.flatMap((u) => groups[u])

  // ── Selection helpers ──
  const toggleSelect = useCallback((id: string) => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  const clearSelection = useCallback(() => setSelected(new Set()), [])

  // ── Focus helpers ──
  const focusItem = useCallback((id: string) => {
    setFocusedId(id)
    const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${id}"]`)
    el?.focus()
    el?.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
  }, [])

  // ── Refresh ──
  const refresh = useCallback(() => {
    router.refresh()
  }, [router])

  // ── Keyboard shortcuts ──
  useInboxShortcuts({
    onNavigateDown: () => {
      if (orderedItems.length === 0) return
      const idx = orderedItems.findIndex((i) => i.id === focusedId)
      const next = idx === -1 ? 0 : Math.min(idx + 1, orderedItems.length - 1)
      focusItem(orderedItems[next].id)
    },
    onNavigateUp: () => {
      if (orderedItems.length === 0) return
      const idx = orderedItems.findIndex((i) => i.id === focusedId)
      const prev = idx <= 0 ? 0 : idx - 1
      focusItem(orderedItems[prev].id)
    },
    onArchiveFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      el?.querySelector<HTMLElement>('[aria-label="More options"]')?.click()
    },
    onAssignFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      el?.querySelector<HTMLElement>('[aria-label="Assign to team member"]')?.click()
    },
    onResolveFocused: () => {
      if (!focusedId) return
      const el = document.querySelector<HTMLElement>(`[data-inbox-item-id="${focusedId}"]`)
      el?.querySelector<HTMLElement>('[aria-label="More options"]')?.click()
    },
    onToggleFocusedCheckbox: () => {
      if (focusedId) toggleSelect(focusedId)
    },
    onShowCheatsheet: () => setShowCheatsheet(true),
  })

  // ── Tabs with badge ──
  const tabs: PageTab[] = TABS.map((t) =>
    t.key === 'all' && visibleItems.length > 0
      ? { ...t, badge: visibleItems.length }
      : t,
  )

  const selectedItems: SelectedItem[] = orderedItems
    .filter((i) => selected.has(i.id))
    .map((i) => ({ id: i.id, type: i.type }))

  const hasNonEmpty = URGENCY_ORDER.some((u) => groups[u].length > 0)

  return (
    <>
      <div className={cn('flex min-h-full flex-col bg-[var(--color-page-bg)]')}>
        <PageHeader
          title="Inbox"
          description="Action items that need your attention"
          actions={
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowCheatsheet(true)}
              aria-label="Show keyboard shortcuts"
              className="h-8 w-8 p-0 text-muted-foreground/60 hover:text-foreground"
            >
              <Keyboard className="h-4 w-4" aria-hidden="true" />
            </Button>
          }
        />

        <div className="px-6">
          <PageTabs
            tabs={tabs}
            activeKey={activeTab}
            currentPlan={currentPlan}
            currentRole={currentRole}
            className="mb-4"
          />
        </div>

        {/* Batch action bar */}
        {selected.size > 0 && (
          <div className="px-6 mb-3" aria-live="polite">
            <BatchActionBar
              selected={selectedItems}
              members={members}
              currentUserId={currentUserId}
              onClear={clearSelection}
              onRefresh={refresh}
            />
          </div>
        )}

        {/* Archived toggle */}
        <div className="px-6 mb-2 flex items-center justify-end">
          <button
            type="button"
            onClick={() => setShowArchived((v) => !v)}
            className="text-[11px] text-muted-foreground/60 hover:text-muted-foreground transition-colors"
          >
            {showArchived ? 'Hide archived' : 'Show archived & resolved'}
          </button>
        </div>

        {/* Urgency-grouped list */}
        <div className="flex-1 space-y-3 px-6 pb-8">
          {!hasNonEmpty ? (
            <EmptyState
              icon={Inbox}
              title="Inbox is clear"
              description={
                activeTab === 'all'
                  ? "You're all caught up. New action items appear here automatically."
                  : 'No items in this category right now.'
              }
            />
          ) : (
            URGENCY_ORDER.map((urgency) => {
              const groupItems = groups[urgency]
              if (groupItems.length === 0) return null
              const defaultExpanded = urgency === 'now' || urgency === 'today'

              return (
                <UrgencyGroup
                  key={urgency}
                  urgency={urgency}
                  count={groupItems.length}
                  defaultExpanded={defaultExpanded}
                >
                  {groupItems.map((item) => (
                    <InboxItemRow
                      key={item.id}
                      item={item}
                      urgency={urgency}
                      isSelected={selected.has(item.id)}
                      isFocused={focusedId === item.id}
                      members={members}
                      currentUserId={currentUserId}
                      onToggleSelect={toggleSelect}
                      onFocus={setFocusedId}
                      onRefresh={refresh}
                    />
                  ))}
                </UrgencyGroup>
              )
            })
          )}
        </div>
      </div>

      {/* Keyboard shortcuts cheatsheet */}
      <Dialog open={showCheatsheet} onOpenChange={setShowCheatsheet}>
        <DialogContent className="max-w-xs">
          <DialogHeader>
            <DialogTitle className="text-sm font-semibold">Keyboard shortcuts</DialogTitle>
          </DialogHeader>
          <div className="mt-2 space-y-1.5">
            {INBOX_SHORTCUTS.map(({ key, description }) => (
              <div key={key} className="flex items-center justify-between gap-4">
                <span className="text-xs text-muted-foreground">{description}</span>
                <kbd className="inline-flex h-5 min-w-[1.25rem] items-center justify-center rounded border border-border/60 bg-muted px-1 text-[10px] font-mono text-foreground">
                  {key}
                </kbd>
              </div>
            ))}
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { InboxClient } from '@/components/inbox/InboxClient'
import type { RichInboxItem, InboxItemType } from '@/components/inbox/InboxClient'
import type { TeamMember } from '@/components/inbox/AssignUserPicker'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

export const metadata: Metadata = {
  title: 'Inbox — InkOS',
}

export default async function InboxPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { studioId, role, plan } = activeStudio
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()
  const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()

  // Fetch all data sources in parallel
  const [
    pendingBookingsRes,
    consentSubmissionsRes,
    waitlistRes,
    newClientsRes,
    assignmentsRes,
    membersRes,
  ] = await Promise.all([
    // 1. Pending bookings — include scheduled_at for urgency
    supabase
      .from('bookings')
      .select('id, created_at, scheduled_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'pending')
      .eq('deposit_paid', false)
      .order('scheduled_at', { ascending: true })
      .limit(50),

    // 2. Consent form submissions (not signed, last 7d)
    supabase
      .from('consent_form_submissions')
      .select('id, client_id, created_at, bookings(scheduled_at), clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .gte('created_at', sevenDaysAgo)
      .is('soft_deleted_at', null)
      .is('signed_at', null)
      .order('created_at', { ascending: false })
      .limit(30),

    // 3. Waitlist entries (last 24h)
    supabase
      .from('waitlist_entries')
      .select('id, client_id, created_at, clients(first_name, last_name)')
      .eq('studio_id', studioId)
      .eq('status', 'active')
      .gte('created_at', oneDayAgo)
      .order('created_at', { ascending: false })
      .limit(20),

    // 4. New clients (last 7d)
    supabase
      .from('clients')
      .select('id, first_name, last_name, created_at')
      .eq('studio_id', studioId)
      .gte('created_at', sevenDaysAgo)
      .is('archived_at', null)
      .order('created_at', { ascending: false })
      .limit(10),

    // 5. Inbox assignments (non-resolved, non-archived)
    supabase
      .from('inbox_assignments')
      .select('item_kind, item_id, assigned_to, snoozed_until, archived_at, resolved_at')
      .eq('studio_id', studioId),

    // 6. Studio members for assignment picker
    supabase
      .from('studio_members')
      .select('user_id, role, profiles(full_name, avatar_url)')
      .eq('studio_id', studioId)
      .is('deactivated_at', null),
  ])

  // Build assignment map: key = `${kind}-${item_id}`
  type AssignmentState = {
    assignedTo: string | null
    snoozedUntil: string | null
    archivedAt: string | null
    resolvedAt: string | null
  }

  const assignmentMap = new Map<string, AssignmentState>()
  for (const a of assignmentsRes.data ?? []) {
    assignmentMap.set(`${a.item_kind}-${a.item_id}`, {
      assignedTo: a.assigned_to,
      snoozedUntil: a.snoozed_until,
      archivedAt: a.archived_at,
      resolvedAt: a.resolved_at,
    })
  }

  function getAssignment(kind: InboxItemType, itemId: string): AssignmentState {
    return assignmentMap.get(`${kind}-${itemId}`) ?? {
      assignedTo: null,
      snoozedUntil: null,
      archivedAt: null,
      resolvedAt: null,
    }
  }

  // Normalize into RichInboxItem[]
  const items: RichInboxItem[] = []

  // Pending bookings (deposit overdue)
  for (const booking of pendingBookingsRes.data ?? []) {
    const clientRow = Array.isArray(booking.clients) ? booking.clients[0] : booking.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('deposit', booking.id)

    items.push({
      id: `booking-${booking.id}`,
      type: 'deposit' as InboxItemType,
      title: 'Deposit pending',
      subtitle: clientName,
      actionLabel: 'View booking',
      actionHref: `/bookings/${booking.id}`,
      timestamp: booking.created_at,
      scheduledAt: booking.scheduled_at,
      ...a,
    })
  }

  // Unsigned consent form submissions
  for (const sub of consentSubmissionsRes.data ?? []) {
    const clientRow = Array.isArray(sub.clients) ? sub.clients[0] : sub.clients
    const bookingRow = Array.isArray(sub.bookings) ? sub.bookings[0] : sub.bookings
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('form', sub.id)

    items.push({
      id: `consent-${sub.id}`,
      type: 'form' as InboxItemType,
      title: 'Consent form unsigned',
      subtitle: clientName,
      actionLabel: 'Review',
      actionHref: `/consent-forms/submissions/${sub.id}`,
      timestamp: sub.created_at,
      scheduledAt: bookingRow?.scheduled_at ?? null,
      ...a,
    })
  }

  // Waitlist entries
  for (const entry of waitlistRes.data ?? []) {
    const clientRow = Array.isArray(entry.clients) ? entry.clients[0] : entry.clients
    const clientName = clientRow
      ? `${clientRow.first_name}${clientRow.last_name ? ` ${clientRow.last_name}` : ''}`
      : 'Client'
    const a = getAssignment('waitlist', entry.id)

    items.push({
      id: `waitlist-${entry.id}`,
      type: 'waitlist' as InboxItemType,
      title: 'New waitlist signup',
      subtitle: clientName,
      actionLabel: 'View',
      actionHref: `/clients/${entry.client_id}`,
      timestamp: entry.created_at,
      scheduledAt: null,
      ...a,
    })
  }

  // New clients
  for (const client of newClientsRes.data ?? []) {
    const clientName = `${client.first_name}${client.last_name ? ` ${client.last_name}` : ''}`
    const a = getAssignment('client', client.id)

    items.push({
      id: `client-${client.id}`,
      type: 'client' as InboxItemType,
      title: 'New client',
      subtitle: clientName,
      actionLabel: 'View',
      actionHref: `/clients/${client.id}`,
      timestamp: client.created_at,
      scheduledAt: null,
      ...a,
    })
  }

  // Sort by timestamp descending
  items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())

  // Build team members list for assignment picker
  const members: TeamMember[] = (membersRes.data ?? []).map((m) => {
    const profileRow = Array.isArray(m.profiles) ? m.profiles[0] : m.profiles
    return {
      userId: m.user_id,
      name: profileRow?.full_name ?? m.user_id,
      role: m.role,
      avatarUrl: profileRow?.avatar_url ?? null,
    }
  })

  return (
    <InboxClient
      items={items}
      members={members}
      currentUserId={user.id}
      currentPlan={plan as PlanTier}
      currentRole={role as NavRole}
    />
  )
}

