/**
 * Resend the consent form link for a given submission.
 */
export async function resendFormLinkAction(
  submissionId: string,
): Promise<ActionResult> {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()

  const { data: submission, error: subErr } = await supabase
    .from('consent_form_submissions')
    .select('id, token, clients!inner(first_name, email)')
    .eq('id', submissionId)
    .eq('studio_id', studioId)
    .single()

  if (subErr || !submission) {
    return { ok: false, error: 'Submission not found' }
  }

  const client = Array.isArray(submission.clients) ? submission.clients[0] : submission.clients
  const email = client?.email

  if (!email) {
    return { ok: false, error: 'Client has no email on file' }
  }

  try {
    const { sendEmail } = await import('@/lib/email/resend')
    const formUrl = `${process.env.NEXT_PUBLIC_APP_URL ?? ''}/consent/${submission.token}`
    await sendEmail({
      to: email,
      template: 'booking_confirmation',
      data: {
        studioName: 'Your Studio',
        clientFirstName: client.first_name ?? 'there',
        serviceName: 'Your appointment',
        artistName: '',
        scheduledAt: new Date().toISOString(),
        endAt: new Date().toISOString(),
        durationMin: 0,
        priceCents: 0,
        depositCents: 0,
        depositPaid: false,
        bookingReference: '',
        depositPaymentUrl: formUrl,
      },
    })
  } catch (err) {
    logger.error({ err, submissionId }, 'inbox: form link resend failed')
    return { ok: false, error: 'Failed to send email' }
  }

  const resolveResult = await upsertAssignment(studioId, 'form', submissionId, {
    resolved_at: new Date().toISOString(),
    note: 'Form link resent via email',
  })

  return resolveResult
}

